INSERT INTO dump_descriptions (base_key, description) VALUES ('apurplegunge-nomist', 'Recolors Goo Cannon corrosion visuals purple, including particles, decals, and status icons, and replaces the corrosive death effect with an empty Niagara system to remove its mist.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('apurplegunge_withmist', 'Recolors Goo Cannon corrosion visuals purple, including particles, decals, and status icons, while retaining the corrosive death mist effect.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
